INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Koordination des Teams Teil der Durchführung?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Zusammenarbeit"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Durchführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat die Koordination des Teams?', 3, '[{"text": "Effiziente Aufgabenverteilung", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}, {"text": "Planung neu erstellen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination sorgt für Zusammenarbeit. b) Sie erfolgt nur in der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Durchführung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Teamkoordination?', 4, '[{"text": "Kommunikation", "correct": true, "because": "Fördert Austausch"}, {"text": "Unklare Rollen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Aufgabenverteilung", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Konfliktmanagement", "correct": true, "because": "Löst Spannungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Teamkoordination erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zusammenarbeit fehlt"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Teamkoordination?', 3, '[{"text": "Kommunikationsplattform", "correct": true, "because": "Fördert Austausch"}, {"text": "Keine Kommunikation", "correct": false, "because": "Fehlt Zusammenarbeit"}, {"text": "Zufällige Anweisungen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Teamkoordination nur für große Teams relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zur Teamkoordination?', 3, '[{"text": "Zuweisung von Arbeitspaketen", "correct": true, "because": "Definiert Rollen"}, {"text": "Projektziele neu setzen", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination nutzt den Projektstrukturplan. b) Sie ist immer problemlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Konflikte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Teamkoordination?', 3, '[{"text": "Aufgabenüberschneidung entsteht", "correct": true, "because": "Keine Abstimmung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Teamkoordination ohne Kommunikation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Austausch essenziell"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Teamkoordination?', 3, '[{"text": "Meeting zur Aufgabenabstimmung", "correct": true, "because": "Klar und konkret"}, {"text": "Irgendwas machen lassen", "correct": false, "because": "Zu vage"}, {"text": "Team soll allein klarkommen", "correct": false, "because": "Keine Koordination"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Teamkoordination nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Zusammenarbeit"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Teamkoordination?', 4, '[{"text": "Rollenklarheit", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Keine Kommunikation", "correct": false, "because": "Erschwert Koordination"}, {"text": "Zeitplan", "correct": true, "because": "Steuert Ablauf"}, {"text": "Teamgröße", "correct": true, "because": "Beeinflusst Abstimmung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Teamkoordination dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Teamkoordination?', 3, '[{"text": "Synchronisation der Arbeiten", "correct": true, "because": "Fördert Effizienz"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Controlling-Aspekt"}, {"text": "Technische Lösung finden", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Teamkoordination ohne Zeitplan erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Teamkoordination?', 3, '[{"text": "Mangelnde Kommunikation", "correct": true, "because": "Verhindert Abstimmung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Koordination"}, {"text": "Definierte Rollen", "correct": false, "because": "Unterstützt Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination sichert Effizienz. b) Sie ist nur für technische Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Teamkoordination?', 3, '[{"text": "Reibungslose Zusammenarbeit", "correct": true, "because": "Fördert Ablauf"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Abstimmung", "correct": false, "because": "Fördert Effizienz"}]');
